DROP TABLE IF EXISTS `forecast_daily`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `forecast_daily` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `day` date NOT NULL,
  `transaction_type` enum('IN','OUT') NOT NULL,
  `yhat` double NOT NULL,
  `yhat_lower` double DEFAULT NULL,
  `yhat_upper` double DEFAULT NULL,
  `model` varchar(64) NOT NULL DEFAULT 'sarimax_v1',
  `run_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_day_type_model` (`day`,`transaction_type`,`model`)
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
